/*
 * A202820  The left-hand half-triangle of A202704.
 * https://oeis.org/A202820
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl, more
 * Formula:   not stated
 * Range:     u8 n <= 21, u16 n <= 21, u32 n <= 21, u64 n <= 21, u128 n <= 21,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  A202820: left‑hand half‑triangle of A202704
 *
 *  The sequence is generated by a triangular array.  Let R[i][j] be
 *  the j‑th element of the i‑th row (1‑based, row i has i elements).
 *  For i = 1:  R[1][1] = 0.
 *
 *  For i > 1:
 *    • If i is odd:
 *          R[i][1] = sum_{k=1}^{i-1} R[i-1][k]
 *                     + sum_{k=1}^{i-1} k·R[i-1][k]
 *                     + 1
 *          For j = 2…i:  R[i][j] = R[i][j-1] + R[i-1][j-1]
 *    • If i is even:
 *          R[i][i] = 0
 *          For j = i-1…1:  R[i][j] = R[i][j+1] + R[i-1][j]
 *
 *  The sequence a(n) is obtained by reading the triangle left‑to‑right,
 *  row by row:  a(1)=R[1][1], a(2)=R[2][1], a(3)=R[2][2], a(4)=R[3][1], …
 *
 *  This implementation builds rows incrementally, caching the values
 *  so each term is computed only once per program run.
 */

#include <stddef.h>
#include <stdlib.h>
#include <string.h>

seq_t a(idx_t n) {
    /* static cache for already computed values */
    static seq_t *cache = NULL;
    static size_t cache_size = 0;
    static size_t cache_cap  = 0;
    static seq_t *prev_row = NULL;   /* previous row's values   */
    static size_t prev_len = 0;      /* length of previous row  */
    static idx_t  rows_computed = 0;

    /* Ensure that at least `n` terms are available in the cache. */
    while (cache_size < n) {
        /* compute next row, row_index = rows_computed + 1   */
        size_t row_index = (size_t)(rows_computed + 1);
        size_t row_len   = row_index;

        seq_t *row = (seq_t *)malloc(row_len * sizeof(seq_t));
        if (!row) {
            /* Allocation failed – return 0 as a safe fallback. */
            return (seq_t)0;
        }

        if (row_index == 1) {
            /* base case: R[1][1] = 0 */
            row[0] = (seq_t)0;
        } else if ((row_index & 1) == 0) {
            /* even row: last element = 0, build backwards */
            row[row_len - 1] = (seq_t)0;
            for (int j = (int)row_len - 2; j >= 0; --j) {
                row[j] = row[j + 1] + prev_row[j];
            }
        } else {
            /* odd row: compute starting value */
            seq_t sum_prev = (seq_t)0;
            seq_t weighted = (seq_t)0;
            for (size_t j = 0; j < prev_len; ++j) {
                sum_prev += prev_row[j];
                weighted += (seq_t)(j + 1) * prev_row[j];
            }
            seq_t start = sum_prev + weighted + (seq_t)1;
            row[0] = start;
            for (size_t j = 1; j < row_len; ++j) {
                row[j] = row[j - 1] + prev_row[j - 1];
            }
        }

        /* Append the new row into the global cache */
        if (cache_size + row_len > cache_cap) {
            size_t new_cap = (cache_cap == 0) ? row_len * 2 : cache_cap * 2;
            seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
            if (!tmp) {
                free(row);
                return (seq_t)0; /* allocation failure */
            }
            cache = tmp;
            cache_cap = new_cap;
        }
        memcpy(cache + cache_size, row, row_len * sizeof(seq_t));
        cache_size += row_len;

        /* prepare for next iteration */
        free(prev_row);
        prev_row = row;
        prev_len = row_len;
        rows_computed++;
    }

    /* retrieve cached value (offset 1) */
    return cache[n - 1];
}
